import { bootstrapDemo, createAppointment, DomainError, listSalons,
  salonDashboard, updateAppointmentStatus } from './server/domain.mjs';

const page = "<!doctype html>\n<html lang=\"tr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Günlük ajanda · Makas</title>\n<style>\n:root{color-scheme:light;--paper:#faf9f5;--surface:#fffefa;--ink:#232c27;--muted:#526058;--line:#d9ded6;--green:#254735;--red:#813b2f;--serif:Georgia,'Times New Roman',serif;font:100%/1.5 'DM Sans',system-ui,sans-serif}\n*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--paper)}[hidden]{display:none!important}\nbutton,input,select{font:inherit;color:inherit}button{cursor:pointer}button:disabled{cursor:default;opacity:.58}\nbutton,input,select{min-height:44px;border:1px solid var(--line);border-radius:5px;background:var(--surface);padding:8px 14px}\nbutton:hover:enabled{border-color:#718578}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #568261;outline-offset:2px}\n.primary{background:var(--green);border-color:var(--green);color:white;font-weight:650}.danger{background:var(--red);border-color:var(--red);color:white}\n.wrap{width:min(1080px,calc(100% - 48px));margin-inline:auto}\nheader{background:var(--surface);border-bottom:1px solid var(--line)}.bar{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:74px}.brand{font:600 27px var(--serif);letter-spacing:-.05em}.brand i{color:#945340}.submark{border-left:1px solid var(--line);padding-left:14px;margin-left:14px;color:var(--muted);font:500 14px system-ui}.lab-picker{display:flex;align-items:center;gap:10px;color:var(--muted);font-size:14px}.lab-picker select{max-width:50vw;color:var(--ink)}\nmain{padding:40px 0 70px}h1,h2,h3,p{margin:0}h1{font:500 clamp(32px,4.4vw,54px)/1.15 var(--serif);letter-spacing:-.045em}.heading,.agenda-heading{display:flex;justify-content:space-between;align-items:center;gap:16px}.kicker,.muted{color:var(--muted)}.kicker{margin-bottom:5px;font-size:14px}\n.agenda{margin-top:28px;border-top:2px solid var(--green);background:var(--surface);border-bottom:1px solid var(--line)}.agenda-heading{padding:22px 0 14px;flex-wrap:wrap}.agenda-heading h2{font:500 clamp(22px,3vw,31px)/1.24 var(--serif);letter-spacing:-.025em}.controls{display:flex;align-items:center;gap:5px;flex-wrap:wrap}.controls button,.controls input{padding:6px 11px;font-size:14px}.date-arrow{min-width:44px}\n.summary{padding:0 0 14px;color:var(--muted);font-size:14px;border-bottom:1px solid var(--line)}\n#list{list-style:none;margin:0;padding:0}.booking{display:grid;grid-template-columns:88px minmax(0,1fr) auto auto;align-items:center;gap:16px;padding:17px 0;border-bottom:1px solid var(--line)}.booking:last-child{border:0}.time{font-variant-numeric:tabular-nums;font-size:18px;font-weight:650}.time small{display:block;color:var(--muted);font-weight:400;font-size:14px}.booking h3{font:600 17px/1.35 system-ui;overflow-wrap:anywhere}.booking p{font-size:14px;color:var(--muted);overflow-wrap:anywhere}.status{font-size:14px;color:var(--muted)}.status.arrived,.status.completed{color:var(--green)}.status.cancelled,.status.no_show{color:var(--red)}.edit-status{font-size:14px}\n.empty{padding:30px 0;color:var(--muted)}details{margin-top:16px;border-bottom:1px solid var(--line)}summary{font-weight:600;cursor:pointer;padding:12px 0;min-height:44px}details ul{padding-left:20px}details li{margin-block:6px}.error{color:var(--red);margin:8px 0;font-weight:550}\ndialog{background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:9px;width:min(440px,calc(100% - 24px));max-height:90dvh;padding:24px;box-shadow:0 15px 70px #10201a29}dialog::backdrop{background:#15221db3}dialog h2{font:500 29px/1.25 var(--serif);margin-bottom:6px}dialog p{overflow-wrap:anywhere}.form{display:grid;gap:12px;margin-top:18px}.form label{font-weight:600;font-size:14px;display:grid;gap:5px}.form select,.form input{min-width:0;width:100%;font-weight:400;font-size:16px}.buttons{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end;margin-top:6px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}\n@media(max-width:620px){.wrap{width:calc(100% - 32px)}.bar{padding:10px 0;align-items:flex-start}.submark{display:block;border:0;padding:0;margin:1px 0 0;font-size:12px}.lab-picker{display:grid;gap:0;font-size:12px}.lab-picker select{max-width:55vw;padding:4px 8px}main{padding-top:22px}.heading{gap:4px;align-items:flex-end}.heading .primary{font-size:14px;padding:8px 10px}.agenda{margin-top:20px}.agenda-heading{gap:10px}.controls{width:100%}.controls input{min-width:0;max-width:100%;flex:1}.booking{grid-template-columns:55px minmax(0,1fr) auto;gap:4px 8px}.booking .status{grid-column:2}.edit-status{grid-column:3;grid-row:1/3;padding:6px}.time{grid-row:1/3}.summary{font-size:13px}}\n</style>\n<script src=\"/app.js\" defer></script>\n</head>\n<body>\n<header><div class=\"bar wrap\"><div><span class=\"brand\">Makas<i>.</i></span><span class=\"submark\">İşletme paneli</span></div><label class=\"lab-picker\">Laboratuvar salonu<select id=\"salon\" disabled><option>Yükleniyor…</option></select></label></div></header>\n<main class=\"wrap\">\n<section class=\"heading\"><div><p id=\"shop-name\" class=\"kicker\">İşletme paneli</p><h1>Günlük ajanda</h1></div><button id=\"add\" class=\"primary\" hidden>Yeni randevu</button></section>\n<p id=\"announcement\" class=\"sr-only\" role=\"status\"></p>\n<div id=\"content\"><p class=\"empty\" role=\"status\">Ajanda yükleniyor…</p></div>\n</main>\n<dialog id=\"editor\" aria-labelledby=\"dialog-title\"><h2 id=\"dialog-title\"></h2><p class=\"muted\" id=\"context\"></p>\n<form id=\"editor-form\" class=\"form\"><div class=\"form\" id=\"fields\"></div><p id=\"feedback\" role=\"alert\" class=\"error\" hidden></p><div class=\"buttons\"><button type=\"button\" id=\"dismiss\">Vazgeç</button><button type=\"submit\" id=\"submit\" class=\"primary\">Kaydet</button></div></form></dialog>\n</body></html>\n";
const script = "const $ = selector => document.querySelector(selector);\nconst select = $('#salon');\nconst content = $('#content');\nconst modal = $('#editor');\nconst form = $('#editor-form');\nconst labels = { confirmed: 'Bekliyor', arrived: 'Geldi', completed: 'Tamamlandı', no_show: 'Gelmedi', cancelled: 'İptal edildi' };\nconst transitions = { confirmed: ['arrived', 'completed', 'no_show', 'cancelled'], arrived: ['completed', 'cancelled'] };\nconst dayFormat = new Intl.DateTimeFormat('tr-TR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });\nconst lira = new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY', maximumFractionDigits: 0 });\nconst esc = value => String(value ?? '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst today = () => new Date().toLocaleDateString('sv-SE', {timeZone:'Europe/Istanbul'});\nconst asDate = day => new Date(day + 'T12:00:00Z');\nconst time = minute => [Math.floor(minute / 60), minute % 60].map(n => String(n).padStart(2, '0')).join(':');\nconst option = (id, name) => '<option value=\"' + esc(id) + '\">' + esc(name) + '</option>';\nlet day = today();\nlet dashboard;\nlet sequence = 0;\nlet editor;\nlet busy = false;\n\nasync function api(path, data) {\n  const options = {cache:'no-store'};\n  if (data !== undefined) Object.assign(options, {\n    method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(data),\n  });\n  const response = await fetch(path, options);\n  const body = await response.json();\n  if (!response.ok) {\n    const error = new Error(body.error || 'İşlem başarısız.');\n    error.code = body.code;\n    throw error;\n  }\n  return body;\n}\nconst pathFor = salonId => '/api/salons/' + encodeURIComponent(salonId);\nfunction showLoadError(error, retry) {\n  content.innerHTML = '<p class=\"error\" role=\"alert\">' + esc(error.message) + '</p><button>Tekrar dene</button>';\n  content.querySelector('button').onclick = retry;\n}\nasync function boot() {\n  try {\n    const {salons} = await api('/api/salons');\n    if (!salons.length) {\n      select.innerHTML = option('', 'Salon bulunmuyor');\n      content.innerHTML = '<p class=\"empty\">Laboratuvardaki kurgusal salonları oluşturup ajandalarını deneyebilirsiniz.</p><button id=\"seed\" class=\"primary\">Örnek salonları oluştur</button>';\n      $('#seed').onclick = async event => {\n        event.currentTarget.disabled = true;\n        try { await api('/api/bootstrap', {}); await boot(); }\n        catch (error) { showLoadError(error, boot); }\n      };\n      return;\n    }\n    select.innerHTML = salons.map(s => option(s.id, s.name)).join('');\n    select.disabled = false;\n    await load();\n  } catch (error) { showLoadError(error, boot); }\n}\nasync function load() {\n  const generation = ++sequence;\n  const id = select.value;\n  dashboard = null;\n  $('#shop-name').textContent = select.selectedOptions[0]?.textContent || 'İşletme paneli';\n  $('#add').hidden = true;\n  content.innerHTML = '<p class=\"empty\" role=\"status\">Ajanda yükleniyor…</p>';\n  try {\n    const result = await api(pathFor(id));\n    if (generation !== sequence || id !== select.value) return;\n    dashboard = result;\n    render();\n  } catch (error) { if (generation === sequence) showLoadError(error, load); }\n}\nfunction render() {\n  const {salon, services, staff, appointments} = dashboard;\n  $('#shop-name').textContent = salon.name + ' · ' + salon.location;\n  $('#add').hidden = !services.length || !staff.length;\n  const rows = appointments.filter(a => a.day === day).sort((a,b) => a.startMinute - b.startMinute || a.staffName.localeCompare(b.staffName,'tr'));\n  const count = status => rows.filter(row => row.status === status).length;\n  const summary = Object.entries(labels).map(([status, label]) => {\n    const n = count(status);\n    return n ? n + ' ' + label.toLocaleLowerCase('tr') : '';\n  }).filter(Boolean).join(' · ');\n  const list = rows.map(a =>\n    '<li class=\"booking\"><div class=\"time\">' + time(a.startMinute) + '<small>' + time(a.endMinute) + '</small></div>' +\n    '<div><h3>' + esc(a.customerName) + '</h3><p>' + esc(a.serviceName) + ' · ' + esc(a.staffName) + '</p></div>' +\n    '<span class=\"status ' + esc(a.status) + '\">' + esc(labels[a.status]) + '</span>' +\n    (transitions[a.status] ? '<button class=\"edit-status\" data-id=\"' + esc(a.id) + '\" aria-label=\"' + esc(a.customerName + ' için durum değiştir') + '\">Durum değiştir</button>' : '') + '</li>').join('');\n  content.innerHTML = '<section class=\"agenda\" aria-labelledby=\"agenda-day\"><div class=\"agenda-heading\"><h2 id=\"agenda-day\">' + dayFormat.format(asDate(day)) + '</h2>' +\n    '<div class=\"controls\"><button class=\"date-arrow\" data-delta=\"-1\" aria-label=\"Önceki gün\">‹</button><input id=\"date\" type=\"date\" min=\"0001-01-01\" max=\"9999-12-31\" aria-label=\"Ajanda tarihi\" value=\"' + esc(day) + '\"><button class=\"date-arrow\" data-delta=\"1\" aria-label=\"Sonraki gün\">›</button><button id=\"today\">Bugün</button></div></div>' +\n    '<p class=\"summary\">' + (summary || '0 randevu') + '</p>' +\n    (rows.length ? '<ul id=\"list\">' + list + '</ul>' : '<p class=\"empty\">Bu gün için kayıtlı randevu yok.</p>') + '</section>' +\n    '<details><summary>Hizmetler (' + services.length + ')</summary><ul>' + services.map(s=>'<li>' + esc(s.name) + ' · ' + s.duration + ' dk · ' + lira.format(s.price) + '</li>').join('') + '</ul></details>' +\n    '<details><summary>Çalışanlar (' + staff.length + ')</summary><ul>' + staff.map(s=>'<li>' + esc(s.name) + ' · ' + esc(s.role) + '</li>').join('') + '</ul></details>';\n}\nfunction setDate(value, focusSelector) {\n  if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(value) || value < '0001-01-01') return;\n  day = value;\n  render();\n  if (focusSelector) $(focusSelector)?.focus();\n  $('#announcement').textContent = dayFormat.format(asDate(day));\n}\ncontent.addEventListener('change', event => {\n  if (event.target.id === 'date' && event.target.validity.valid && event.target.value) setDate(event.target.value, '#date');\n});\ncontent.addEventListener('click', event => {\n  const button = event.target.closest('button');\n  if (!button || !dashboard) return;\n  if (button.dataset.delta) {\n    const date = asDate(day);\n    date.setUTCDate(date.getUTCDate() + Number(button.dataset.delta));\n    setDate(date.toISOString().slice(0,10), '[data-delta=\"' + button.dataset.delta + '\"]');\n  }\n  if (button.id === 'today') setDate(today(), '#today');\n  if (button.dataset.id) {\n    const row = dashboard.appointments.find(a=>a.id === button.dataset.id);\n    if (row && transitions[row.status]) openEditor(row);\n  }\n});\nfunction updateSubmit() {\n  const cancel = editor?.row && form.elements.status.value === 'cancelled';\n  $('#submit').textContent = cancel ? 'İptali onayla' : editor?.row ? 'Durumu kaydet' : 'Randevu ekle';\n  $('#submit').className = cancel ? 'danger' : 'primary';\n  const warning = $('#cancel-note');\n  if (warning) warning.hidden = !cancel;\n}\nfunction openEditor(row) {\n  if (!dashboard || busy) return;\n  editor = { salonId: dashboard.salon.id, generation:sequence, row };\n  $('#dialog-title').textContent = row ? 'Randevu durumu' : 'Yeni örnek randevu';\n  $('#context').textContent = row ? [dashboard.salon.name, row.customerName, row.staffName, dayFormat.format(asDate(row.day)),time(row.startMinute)].join(' · ') : dashboard.salon.name;\n  $('#feedback').hidden = true;\n  if (row) {\n    $('#fields').innerHTML = '<label>Yeni durum<select name=\"status\" required><option value=\"\">Durum seçin</option>' +\n      transitions[row.status].map(status=>option(status, status === 'cancelled' ? 'Randevuyu iptal et' : labels[status])).join('') +\n      '</select></label><p id=\"cancel-note\" hidden>Onayladığınızda bu randevu iptal edilir ve saat yeniden açılır.</p>';\n    form.elements.status.onchange = updateSubmit;\n  } else {\n    $('#fields').innerHTML = '<label>Müşteri adı<input name=\"customerName\" minlength=\"2\" maxlength=\"80\" placeholder=\"Örnek müşteri\" required></label><label>Hizmet<select name=\"serviceId\" required>' +\n      dashboard.services.map(s=>option(s.id,s.name)).join('') + '</select></label><label>Çalışan<select name=\"staffId\" required>' +\n      dashboard.staff.map(s=>option(s.id,s.name)).join('') + '</select></label><label>Tarih<input name=\"day\" type=\"date\" value=\"' + esc(day) +\n      '\" required></label><label>Saat<input name=\"time\" type=\"time\" step=\"900\" required></label>';\n  }\n  updateSubmit();\n  modal.showModal();\n}\n$('#add').onclick = () => openEditor(null);\n$('#dismiss').onclick = () => { if (!busy) modal.close(); };\nmodal.addEventListener('cancel', event => { if (busy) event.preventDefault(); });\nselect.onchange = () => {\n  if (modal.open) modal.close();\n  $('#announcement').textContent = '';\n  load();\n};\nform.onsubmit = async event => {\n  event.preventDefault();\n  const state = editor;\n  if (busy || !state || state.salonId !== select.value || state.generation !== sequence) return;\n  const row = state.row;\n  const data = Object.fromEntries(new FormData(form));\n  const body = row ? {appointmentId:row.id, status:data.status, expectedStatus:row.status} : data;\n  const pendingButton = $('#submit');\n  busy = true;\n  pendingButton.disabled = true;\n  $('#dismiss').disabled = true;\n  $('#feedback').hidden = true;\n  try {\n    await api(pathFor(state.salonId) + (row ? '/status' : '/appointments'), body);\n    if (state.generation !== sequence || state.salonId !== select.value) return;\n    if (!row) day = data.day;\n    modal.close();\n    $('#announcement').textContent = row ? 'Randevu durumu kaydedildi.' : 'Randevu eklendi.';\n    await load();\n    if (select.value === state.salonId) {\n      const next = row && content.querySelector('[data-id=\"' + CSS.escape(row.id) + '\"]');\n      (next || $('#date'))?.focus();\n    }\n  } catch (error) {\n    if (state.generation !== sequence) return;\n    if (row && error.code === 'STATUS_CONFLICT') {\n      modal.close();\n      $('#announcement').textContent = 'Randevu başka bir işlemle değişti. Ajanda yenilendi.';\n      await load();\n    } else {\n      $('#feedback').textContent = error.message;\n      $('#feedback').hidden = false;\n    }\n  } finally {\n    busy = false;\n    pendingButton.disabled = false;\n    $('#dismiss').disabled = false;\n  }\n};\nboot();\n";
const security = {
  'Cache-Control': 'no-store',
  'Content-Security-Policy': "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self'; object-src 'none'; frame-ancestors 'none'; base-uri 'none'",
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'no-referrer',
};
const reply = (body, status = 200) => Response.json(body, { status, headers: security });

async function jsonBody(request) {
  const origin = request.headers.get('Origin');
  const expected = new URL(request.url).origin;
  if (origin !== expected) throw new DomainError(403, 'ORIGIN', 'Bu kaynaktan işlem yapılamaz.');
  if (!request.headers.get('content-type')?.startsWith('application/json')) {
    throw new DomainError(415, 'TYPE', 'JSON gönderin.');
  }
  if (Number(request.headers.get('content-length') || 0) > 2048) {
    throw new DomainError(413, 'BODY_TOO_LARGE', 'İstek çok büyük.');
  }
  const raw = await request.text();
  if (raw.length > 2048) throw new DomainError(413, 'BODY_TOO_LARGE', 'İstek çok büyük.');
  try {
    const body = JSON.parse(raw);
    if (!body || Array.isArray(body) || typeof body !== 'object') throw Error();
    return body;
  } catch { throw new DomainError(400, 'INVALID_JSON', 'Geçersiz veri.'); }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === '/' && request.method === 'GET') {
      return new Response(page, { headers: { ...security, 'Content-Type': 'text/html; charset=utf-8' } });
    }
    if (url.pathname === '/app.js' && request.method === 'GET') {
      return new Response(script, { headers: { ...security, 'Content-Type': 'text/javascript; charset=utf-8' } });
    }
    if (!url.pathname.startsWith('/api/')) return new Response('Bulunamadı', { status: 404, headers: security });
    if (!env.DB) return reply({ error: 'Demo veritabanı hazır değil.' }, 503);
    try {
      if (url.pathname === '/api/salons' && request.method === 'GET') {
        return reply({ salons: await listSalons(env.DB) });
      }
      if (url.pathname === '/api/bootstrap' && request.method === 'POST') {
        await jsonBody(request);
        return reply(await bootstrapDemo(env.DB));
      }
      const match = /^\/api\/salons\/([a-z][a-z0-9-]{1,40})(?:\/(appointments|status))?$/.exec(url.pathname);
      if (!match) return reply({ error: 'API bulunamadı.' }, 404);
      const [, id, action] = match;
      if (!action && request.method === 'GET') return reply(await salonDashboard(env.DB, id));
      if (action === 'appointments' && request.method === 'POST') {
        return reply(await createAppointment(env.DB, id, await jsonBody(request)), 201);
      }
      if (action === 'status' && request.method === 'POST') {
        const { appointmentId, status, expectedStatus } = await jsonBody(request);
        return reply(await updateAppointmentStatus(env.DB, id, appointmentId, status, expectedStatus));
      }
      return reply({ error: 'Yöntem desteklenmiyor.' }, 405);
    } catch (error) {
      if (error instanceof DomainError) return reply({ error: error.message, code: error.code }, error.status);
      return reply({ error: 'İşlem tamamlanamadı.' }, 503);
    }
  },
};
